from mcp.server import MCPServer

mcp = MCPServer("ops")


@mcp.resource("schema://orders")  # attached on purpose: @ops:schema://orders
def orders_schema() -> str:
    """The orders database schema, as SQL DDL."""
    return read_doc("schemas/orders.sql")


@mcp.prompt()  # run by a person: /mcp__ops__incident_review INC-2041
def incident_review(incident_id: str) -> str:
    """Start a blameless incident review in the team's format."""
    return render_review(incident_id)


@mcp.tool()  # an action: the model decides, the host asks for approval
async def restart_worker(name: str) -> str:
    """Restart one queue worker by name."""
    return await ops_api.restart(name)
